let __v_3124 = Value::from("Almost all moles are harmless, so what matters is knowing what a change looks like rather than checking it every day: the ABCDE test is not symmetrical, a ragged or blurry border, more than one colour, wider than about 6mm, or anything that is changing. Photograph it beside a coin for scale and compare it every few months; a mole that changes, bleeds, itches or crusts on its own wants a GP within two weeks, and a hair growing out of one usually means it is an ordinary mole that has been there a long time.");
frame.store("_MOLE_ORDINARY_TEXT", __v_3124.clone())?;
